{
  "name": "Neighbor Tim's BBQ",
  "address": "152 -E Aero Camino",
  "city": "Goleta",
  "state": "CA",
  "categories": "Food Trucks, Barbeque, Restaurants, Food Delivery Services, Food, American (New)",
  "hours": {
    "Thursday": "16:45-20:0",
    "Friday": "16:45-20:0",
